            bid = max(63.0, min(90.0, anchor + 2.0))
        else:
            bid = 65.0
        return min(budget, bid)

    if tight_supply:
        if anchor >= 65.0:
            bid = 24.0 if hp >= 6 and no_water_days == 0 else min(88.0, anchor + 1.5)
        elif anchor > 0:
            bid = max(52.0, anchor + 1.5)
        else:
            bid = 55.0
        return min(budget, bid)

    if medium_supply:
        if pressured:
            if anchor > 0:
                bid = max(48.0, min(78.0, anchor + 1.0))
            else:
                bid = 50.0
        else:
            if anchor >= 68.0:
